const $=s=>document.querySelector(s),contexts=[...document.querySelectorAll('canvas')].map(c=>c.getContext('2d'));
const sheet=new Image(),fx=Array.from({length:12},()=>new Image());let loaded=0,ready=false,playing=false,t=0,ct=0,last=0,freeze=0,hit=false,wait=0,audioContext;
function load(){if(++loaded===13){ready=true;document.querySelectorAll('button').forEach(b=>b.disabled=false);draw()}}
sheet.onload=load;sheet.src='assets/flame-sequence.png';fx.forEach((im,i)=>{im.onload=load;im.onerror=()=>$('#time').textContent='素材載入失敗，請重新整理';im.src='assets/flame-fx/frames/frame-'+String(i).padStart(2,'0')+'.png'});
const ab=[0,.22,.4,.56,.74,.84,.96,1.09,1.23,1.45,1.65,1.85,2.06,2.32,2.58,2.86,3.2];
const fb=[.28,.48,.72,.87,1.01,1.1,1.34,1.55,1.78,2.02,2.28,2.6,2.95];
const clamp=v=>Math.max(0,Math.min(1,v));function find(t,b){for(let i=0;i<b.length-1;i++)if(t<b[i+1])return i;return b.length-2}
function ground(x){let g=x.createLinearGradient(0,0,0,400);g.addColorStop(0,'#1b3039');g.addColorStop(1,'#304942');x.fillStyle=g;x.fillRect(0,0,800,400);x.strokeStyle='#8d9d7440';for(let y=310;y<400;y+=22){x.beginPath();x.moveTo(0,y);x.lineTo(800,y);x.stroke()}for(let k=0;k<12;k++){x.beginPath();x.moveTo(400+(k-6)*55,310);x.lineTo(400+(k-6)*95,400);x.stroke()}x.fillStyle='#31484b';for(let k=0;k<6;k++)x.fillRect(25+k*150,135,11,150);x.fillStyle='#101d2255';for(let xx of [155,637]){x.beginPath();x.ellipse(xx,333,53,10,0,0,7);x.fill()}}
function hero(x,at,animated){const sw=sheet.naturalWidth/4,sh=sheet.naturalHeight/4;let wind=animated&&at<.75?Math.sin(clamp(at/.75)*Math.PI):0,push=animated&&at>=.75?Math.exp(-(at-.75)*6):0;x.save();x.translate(157-wind*9+push*9,334);x.rotate(-wind*.075+push*.06);x.scale(1+push*.03,1-wind*.025);x.drawImage(sheet,0,0,210,sh,-145,-310,293,310);x.restore()}
function enemy(x,at,animated,flashed){const sh=sheet.naturalHeight/4,hitAge=at-1.1;let response=animated&&hitAge>=0?Math.exp(-hitAge*5)*Math.sin(Math.min(hitAge*12,Math.PI)):0;x.save();x.translate(640+response*22,334);x.rotate(response*.18);x.drawImage(sheet,245,0,198,sh,-138,-310,277,310);if(flashed&&hitAge>=0&&hitAge<.075){x.globalCompositeOperation='screen';x.globalAlpha=.55*(1-hitAge/.075);x.fillStyle='#fff1c4';x.beginPath();x.ellipse(0,-100,46,74,0,0,7);x.fill()}x.restore()}
function effect(x,at){if(at<fb[0]||at>=fb[12])return;const i=find(at,fb);x.drawImage(fx[i],184,85,504,304)}
function extras(x,at){let age=at-1.1;if(age<0||age>.85)return;const fade=1-age/.85;x.save();x.globalAlpha=fade;for(let i=0;i<22;i++){let a=i*2.39996,s=60+(i%5)*22,px=632+Math.cos(a)*s*age,py=229+Math.sin(a)*s*age+70*age*age;x.fillStyle=i%2?'#ffba4e':'#fff0b3';x.beginPath();x.arc(px,py,2.2*fade,0,7);x.fill()}x.font='bold 24px system-ui';x.fillStyle='#ffe2a2';x.fillText('328',620,135-age*25);x.restore()}
function draw(){if(!ready)return;contexts.forEach((x,index)=>{const at=index===2?ct:t;x.setTransform(1,0,0,1,0,0);x.clearRect(0,0,800,400);x.save();if(index===2&&$('#shake').checked){let age=at-1.1,amp=age>=0?5*Math.exp(-age*10):0;x.translate(Math.sin(age*64)*amp,Math.sin(age*91)*amp*.6)}ground(x);if(index===0){let i=find(Math.min(at,3.199),ab),sw=sheet.naturalWidth/4,sh=sheet.naturalHeight/4;x.drawImage(sheet,(i%4)*sw,Math.floor(i/4)*sh,sw,sh,35,-10,730,365)}else{hero(x,at,index===2&&$('#recoil').checked);enemy(x,at,index===2&&$('#recoil').checked,index===2&&$('#flash').checked);effect(x,at);if(index===2&&$('#flash').checked)extras(x,at)}x.restore();x.font='12px system-ui';x.fillStyle='#b7c9bd';x.fillText((index===2?'C ':'')+Math.min(at,3.4).toFixed(2)+'s',16,28)});$('#scrub').value=t*1000;$('#time').textContent=t.toFixed(2)+' / 3.40秒';$('#play').textContent=playing?'暫停':'同步播放';$('#stage').textContent=t<.72?'蓄力 · 觀察 C 的後座':t<1.1?'噴發 · 觀察焰流形狀':t<1.85?'命中 · 比較 B 與 C 的敵人反應':'消散 · 檢查煙塵與收招';}
function sound(){if(!$('#audio').checked)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();audioContext.resume();let o=audioContext.createOscillator(),g=audioContext.createGain(),now=audioContext.currentTime;o.type='triangle';o.frequency.setValueAtTime(160,now);o.frequency.exponentialRampToValueAtTime(38,now+.22);g.gain.setValueAtTime(.12,now);g.gain.exponentialRampToValueAtTime(.001,now+.3);o.connect(g);g.connect(audioContext.destination);o.start(now);o.stop(now+.32)}catch{}}
function reset(){t=ct=freeze=wait=0;hit=false;draw()}
$('#play').onclick=()=>{if(t>=3.4)reset();playing=!playing;draw()};$('#reset').onclick=()=>{reset();playing=true;draw()};$('#step').onclick=()=>{playing=false;t=Math.min(3.4,t+.13);ct=t;hit=ct>=1.1;freeze=0;draw()};$('#scrub').oninput=()=>{playing=false;t=+$('#scrub').value/1000;ct=t;hit=ct>=1.1;freeze=wait=0;draw()};document.querySelectorAll('.toggles input').forEach(e=>e.onchange=()=>{if(e.id==='stop'){ct=t;freeze=0}draw()});
function tick(now){let real=Math.min((now-last)/1000||0,.05);last=now;if(ready&&playing){let dt=real*(+$('#speed').value);if(t<3.4){t=Math.min(3.4,t+dt);if(freeze>0)freeze=Math.max(0,freeze-real);else ct=Math.min(3.4,ct+dt);if(!hit&&ct>=1.1){ct=1.1;hit=true;if($('#stop').checked)freeze=.08;sound()}}else if($('#loop').checked){wait+=real;if(wait>.7)reset()}else playing=false;draw()}requestAnimationFrame(tick)}requestAnimationFrame(tick);
